SELECT product_id, CASE WHEN unit_price >= 420 THEN 'LARGE' ELSE 'SMALL' END AS unit_price_tier, BIT_AND(quantity) AS quantity_bit_and, CORR(quantity, unit_price) AS corr_quantity_unit_price, CORR(unit_price, quantity) AS corr_unit_price_quantity, COUNT(*) AS row_count, COUNT(*) AS num_rows FROM order_items GROUP BY product_id, CASE WHEN unit_price >= 420 THEN 'LARGE' ELSE 'SMALL' END HAVING COUNT(*) > 1 ORDER BY unit_price_tier ASC NULLS LAST;
